use crate::aap::caps::kb_read;
use crate::aap::caps::tool_llm::{self, Reply};
use crate::aap::caps::types::Intent;

const SYSTEM: &str = "You answer customer support questions using only the material provided. \
If the material does not answer the question, say so.";

/// Bounds the tool-orchestration loop so a model that keeps asking for
/// lookups cannot spin forever.
const MAX_ROUNDS: usize = 3;

struct Node;

impl Guest for Node {
    fn run(ctx: ConversationContext) -> ResponseResult {
        match answer(&ctx) {
            Ok(text) => ResponseResult::Ok(AgentResponse { text }),
            Err(message) => ResponseResult::Error(LlmError { message }),
        }
    }
}

fn answer(ctx: &ConversationContext) -> Result<String, String> {
    let mut prompt = build_prompt(ctx);

    for _ in 0..MAX_ROUNDS {
        match tool_llm::generate(SYSTEM, &prompt) {
            Reply::Text(text) => return Ok(text),
            Reply::Call(req) => {
                // The only tool in scope is `lookup`, backed by kb-read.
                if req.tool != "lookup" {
                    return Err(format!("model requested out-of-scope tool: {}", req.tool));
                }
                let docs = kb_read::lookup(&req.query);
                prompt.push_str("\n\nLookup for \"");
                prompt.push_str(&req.query);
                prompt.push_str("\" returned:\n");
                if docs.is_empty() {
                    prompt.push_str("(no results)\n");
                } else {
                    for doc in &docs {
                        prompt.push_str("- ");
                        prompt.push_str(doc);
                        prompt.push('\n');
                    }
                }
            }
        }
    }

    Err("tool-call budget exhausted without an answer".to_string())
}

fn build_prompt(ctx: &ConversationContext) -> String {
    let mut p = String::new();
    p.push_str("Intent: ");
    p.push_str(intent_label(ctx.intent));
    p.push_str("\n\nKnowledge:\n");
    if ctx.knowledge.is_empty() {
        p.push_str("(none)\n");
    } else {
        for k in &ctx.knowledge {
            p.push_str("- ");
            p.push_str(k);
            p.push('\n');
        }
    }
    p.push_str("\nQuestion:\n");
    p.push_str(&ctx.question);
    p
}

fn intent_label(intent: Intent) -> &'static str {
    match intent {
        Intent::BillingQuestion => "billing-question",
        Intent::TechnicalSupport => "technical-support",
        Intent::AccountChange => "account-change",
        Intent::GeneralInquiry => "general-inquiry",
        Intent::Unknown => "unknown",
    }
}

export!(Node);
